head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil45202";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — briefList, checkPointList, workExampleList, issueDataList, briefDir
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil45202.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return (!(String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))).length === 0) && $c.session.getUserInfo("corpUsrTpCd") === '11'); } }, { id: "c_when_48", fn: function(){ return (!(String(((dma_pageContext.get("briefList") ?? "")) == null ? '' : ((dma_pageContext.get("briefList") ?? ""))).length === 0)); } }, { id: "c_otherwise_53", fn: function(){ return (!((!(String(((dma_pageContext.get("briefList") ?? "")) == null ? '' : ((dma_pageContext.get("briefList") ?? ""))).length === 0)))); } }, { id: "txt_p55", fn: function(){ return ((((dma_pageContext.get("briefList") ?? "")) && typeof ((dma_pageContext.get("briefList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("briefList") ?? "")).getRowCount() : ((((dma_pageContext.get("briefList") ?? "")) == null) ? 0 : (((dma_pageContext.get("briefList") ?? "")).length || 0))) === 0); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return (!(String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))).length === 0) && $c.session.getUserInfo("corpUsrTpCd") === '11'); } }, { id: "c_when_61", fn: function(){ return (!(String(((dma_pageContext.get("checkPointList") ?? "")) == null ? '' : ((dma_pageContext.get("checkPointList") ?? ""))).length === 0)); } }, { id: "c_otherwise_67", fn: function(){ return (!((!(String(((dma_pageContext.get("checkPointList") ?? "")) == null ? '' : ((dma_pageContext.get("checkPointList") ?? ""))).length === 0)))); } }, { id: "txt_p69", fn: function(){ return ((((dma_pageContext.get("checkPointList") ?? "")) && typeof ((dma_pageContext.get("checkPointList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("checkPointList") ?? "")).getRowCount() : ((((dma_pageContext.get("checkPointList") ?? "")) == null) ? 0 : (((dma_pageContext.get("checkPointList") ?? "")).length || 0))) === 0); } }, { id: "if_corpUsrTpCd_3", fn: function(){ return (!(String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))).length === 0) && $c.session.getUserInfo("corpUsrTpCd") === '11'); } }, { id: "c_when_74", fn: function(){ return (!(String(((dma_pageContext.get("workExampleList") ?? "")) == null ? '' : ((dma_pageContext.get("workExampleList") ?? ""))).length === 0)); } }, { id: "c_otherwise_80", fn: function(){ return (!((!(String(((dma_pageContext.get("workExampleList") ?? "")) == null ? '' : ((dma_pageContext.get("workExampleList") ?? ""))).length === 0)))); } }, { id: "txt_p82", fn: function(){ return ((((dma_pageContext.get("workExampleList") ?? "")) && typeof ((dma_pageContext.get("workExampleList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("workExampleList") ?? "")).getRowCount() : ((((dma_pageContext.get("workExampleList") ?? "")) == null) ? 0 : (((dma_pageContext.get("workExampleList") ?? "")).length || 0))) === 0); } }, { id: "c_when_87", fn: function(){ return (!(String(((dma_pageContext.get("issueDataList") ?? "")) == null ? '' : ((dma_pageContext.get("issueDataList") ?? ""))).length === 0)); } }, { id: "c_otherwise_94", fn: function(){ return (!((!(String(((dma_pageContext.get("issueDataList") ?? "")) == null ? '' : ((dma_pageContext.get("issueDataList") ?? ""))).length === 0)))); } }, { id: "txt_p96", fn: function(){ return ((((dma_pageContext.get("issueDataList") ?? "")) && typeof ((dma_pageContext.get("issueDataList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("issueDataList") ?? "")).getRowCount() : ((((dma_pageContext.get("issueDataList") ?? "")) == null) ? 0 : (((dma_pageContext.get("issueDataList") ?? "")).length || 0))) === 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_50", entity: "dlt_briefList", countIds: [], cells: [{ childId: "btn_briefPopView", fn: function (v, i) { return String(v("briefPublNm")); } }] },
        { genId: "c_foreach_63", entity: "dlt_checkPointList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("title")); } }, { childId: "btn_checkPointPopView", fn: function (v, i) { return String(v("contnContn")); } }] },
        { genId: "c_foreach_76", entity: "dlt_workExampleList", countIds: [], cells: [{ childId: "__rc1", fn: function (v, i) { return String(v("title")); } }, { childId: "btn_workExamplePopView", fn: function (v, i) { return String(v("contnContn")); } }] },
        { genId: "c_foreach_91", entity: "dlt_entityBbsAttachVO", countIds: [], cells: [{ childId: "btn_issueDataPopView", fn: function (v, i) { return String(v("attachFileNm")); } }] },
        { genId: "c_foreach_89", entity: "dlt_issueDataList", countIds: [], cells: [{ childId: "__rc2", fn: function (v, i) { return String(v("title")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(search vs brief vs checkpoint vs workexample) — 어느 쪽인지 정할 근거가 없다

