/**
 * @method
 * @name tx_fn_issueDataPopView
 * @description issue Data Pop View 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_issueDataPopView = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/fileDownload.do", "", ($c.util.getComponent("dma_issueDataPopViewReq") ? $c.util.getComponent("dma_issueDataPopViewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

